<script setup>
import{computed,onMounted,reactive,ref}from'vue';import*as api from'../services/dining'
const tab=ref('config'),configTab=ref('stores'),loading=ref(false),error=ref(''),notice=ref(''),modal=ref(''),form=reactive({});const stores=ref([]),tables=ref([]),categories=ref([]),dishes=ref([]),packages=ref([]),orders=ref([]),tickets=ref([]),overview=ref(null),sales=ref([]);const storeId=ref(''),statusFilter=ref(''),verifyCode=ref(''),device=ref('DINING-DESK-01');const today=localDate(new Date()),start=ref(localDate(new Date(Date.now()-29*86400000))),end=ref(localDate(new Date(Date.now()+30*86400000)));const rows=computed(()=>({stores:stores.value,tables:tables.value,categories:categories.value,dishes:dishes.value,packages:packages.value}[configTab.value]||[]));const statusText={ACTIVE:'启用',INACTIVE:'停用',PENDING_PAYMENT:'待支付',PAID:'已支付',PREPARING:'备餐中',READY:'已出餐',DELIVERING:'配送中',VERIFIED:'已核销',COMPLETED:'已完成',CANCELLED:'已取消',REFUND_PENDING:'退款待审',REFUNDING:'退款中',REFUNDED:'已退款',NEW:'新任务',ACCEPTED:'已接单'}
const cards=computed(()=>overview.value?[['订单量',overview.value.orderCount,`已完成 ${overview.value.completedCount}`],['营业额',money(overview.value.salesAmountCent),`已支付 ${overview.value.paidCount} 单`],['就餐人次',overview.value.guestCount,`核销 ${overview.value.verificationCount} 单`],['菜品销售',money(overview.value.dishSalesAmountCent),`套餐 ${money(overview.value.packageSalesAmountCent)}`],['退款订单',overview.value.refundCount,`取消 ${overview.value.cancelledCount}`]]:[])
async function run(fn,msg=''){try{loading.value=true;error.value='';await fn();if(msg)notice.value=msg}catch(e){error.value=e.message}finally{loading.value=false}}
async function loadConfig(){await run(async()=>{[stores.value,tables.value,categories.value,dishes.value,packages.value]=await Promise.all([api.getDiningStores(),api.getDiningTables(),api.getDiningCategories(),api.getDiningDishes(),api.getDiningPackages()])})}
const query=()=>({startDate:start.value,endDate:end.value,storeId:storeId.value||undefined,status:statusFilter.value||undefined});async function loadOrders(){await run(async()=>orders.value=await api.getDiningOrders(query())||[])}async function loadKitchen(){await run(async()=>tickets.value=await api.getKitchenTickets()||[])}async function loadReport(){await run(async()=>{[overview.value,sales.value]=await Promise.all([api.getDiningOverview(query()),api.getDiningDishSales(query())])})}function switchTab(v){tab.value=v;if(v==='orders')loadOrders();if(v==='kitchen')loadKitchen();if(v==='report')loadReport()}
function reset(v){Object.keys(form).forEach(k=>delete form[k]);Object.assign(form,v)}function open(kind,item){modal.value=kind;const d={store:{storeCode:'',name:'',address:'',contactPhone:'',openTime:'08:00',closeTime:'22:00',status:'ACTIVE'},table:{storeId:storeId.value||'',tableCode:'',name:'',tableType:'TABLE',capacity:4,status:'ACTIVE'},category:{storeId:storeId.value||'',categoryCode:'',name:'',sortOrder:0,status:'ACTIVE'},dish:{storeId:storeId.value||'',categoryId:'',dishCode:'',name:'',priceYuan:0,specialPriceYuan:'',imageUrl:'',description:'',recommended:false,special:false,status:'ACTIVE',initialStock:0,warningQuantity:10},package:{storeId:storeId.value||'',packageCode:'',name:'',priceYuan:0,imageUrl:'',description:'',recommended:false,status:'ACTIVE',itemText:''},stock:{operation:'IN',quantity:1,remark:'批量入库'}};reset(item?{...item,priceYuan:item.priceCent/100,specialPriceYuan:item.specialPriceCent==null?'':item.specialPriceCent/100,itemText:(item.items||[]).map(x=>`${x.dishId}:${x.quantity}`).join(',')}:d[kind]);if(kind==='stock')form.dish=item}
async function save(){await run(async()=>{const kind=modal.value,id=form.id;let d={...form};delete d.id;delete d.storeName;delete d.categoryName;delete d.salePriceCent;delete d.onHandQuantity;delete d.lockedQuantity;delete d.availableQuantity;delete d.lowStock;delete d.dish;delete d.itemText;delete d.priceYuan;delete d.specialPriceYuan;if(['table','category','dish','package'].includes(kind))d.storeId=Number(d.storeId);if(kind==='dish'){d.categoryId=Number(d.categoryId);d.priceCent=Math.round(Number(form.priceYuan)*100);d.specialPriceCent=form.specialPriceYuan===''?null:Math.round(Number(form.specialPriceYuan)*100)}if(kind==='package'){d.priceCent=Math.round(Number(form.priceYuan)*100);d.items=String(form.itemText).split(',').filter(Boolean).map(v=>{const[a,b]=v.split(':');return{dishId:Number(a),quantity:Number(b)}})}if(kind==='stock'){await api.adjustDiningStock(form.dish.id,{operation:form.operation,quantity:Number(form.quantity),remark:form.remark,idempotencyKey:`DINING-WEB-${Date.now()}`})}else{const f={store:[api.createDiningStore,api.updateDiningStore],table:[api.createDiningTable,api.updateDiningTable],category:[api.createDiningCategory,api.updateDiningCategory],dish:[api.createDiningDish,api.updateDiningDish],package:[api.createDiningPackage,api.updateDiningPackage]}[kind];id?await f[1](id,d):await f[0](d)}modal.value='';await loadConfig()},'保存成功')}
async function kitchen(v,target){await run(async()=>{await api.updateKitchenTicket(v.id,{status:target,note:''});await loadKitchen();await loadOrders()},`任务已更新为${status(target)}`)}async function consume(){await run(async()=>{await api.consumeDiningVerification({code:verifyCode.value,deviceNo:device.value});verifyCode.value='';await loadOrders()},'核销成功')}async function startDelivery(v){await run(async()=>{await api.startDiningDelivery(v.id);await loadOrders()},'已开始配送')}async function complete(v){await run(async()=>{await api.completeDiningOrder(v.id);await loadOrders()},'订单履约完成')}async function csv(){await run(async()=>{const blob=await api.exportDiningCsv(query()),u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=`餐饮营业台账_${start.value}_${end.value}.csv`;a.click();URL.revokeObjectURL(u)})}function money(v){return`¥${(Number(v||0)/100).toFixed(2)}`}function status(v){return statusText[v]||v||'-'}function dt(v){return v?String(v).replace('T',' ').slice(0,16):'-'}function localDate(d){return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,10)}onMounted(loadConfig)
</script>
<template><div class="dining-page"><div class="toolbar"><div><h2>餐饮预订运营</h2><p>菜品套餐、库存、餐位预订、后厨任务、前台核销与营业报表统一工作台。</p></div><button @click="loadConfig">刷新基础数据</button></div><p v-if="error" class="error msg">{{error}}</p><p v-if="notice" class="success msg">{{notice}}</p><div class="context panel"><label>统计开始<input v-model="start" type="date"></label><label>统计结束<input v-model="end" type="date"></label><label>当前门店<select v-model="storeId"><option value="">全部门店</option><option v-for="v in stores" :key="v.id" :value="v.id">{{v.name}}</option></select></label></div><div class="content-tabs tabs"><button v-for="v in [['config','菜品与门店'],['orders','订单管理'],['kitchen','后厨/前台'],['verify','到店核销'],['report','营业报表']]" :key="v[0]" :class="{active:tab===v[0]}" @click="switchTab(v[0])">{{v[1]}}</button></div>
<section v-if="tab==='config'"><div class="config-nav"><button v-for="v in [['stores','门店'],['tables','餐位/雅间'],['categories','菜品分类'],['dishes','菜品库存'],['packages','套餐']]" :key="v[0]" :class="{active:configTab===v[0]}" @click="configTab=v[0]">{{v[1]}}</button></div><div class="toolbar"><div><h3>基础资料维护</h3><p>支持特价、推荐、图片、套餐组成、实时库存与低库存预警。</p></div><button class="primary" @click="open({stores:'store',tables:'table',categories:'category',dishes:'dish',packages:'package'}[configTab])">新增</button></div><div class="panel table-wrap"><table><thead><tr><th>编码/名称</th><th>门店/分类</th><th>价格/容量</th><th>库存/组成</th><th>标签/状态</th><th>操作</th></tr></thead><tbody><tr v-if="!rows.length"><td colspan="6">暂无数据。</td></tr><tr v-for="v in rows" :key="v.id"><td><b>{{v.name}}</b><small>{{v.storeCode||v.tableCode||v.categoryCode||v.dishCode||v.packageCode}}</small></td><td>{{v.storeName||v.address||'-'}}<small>{{v.categoryName||v.tableType||''}}</small></td><td>{{v.priceCent!=null?money(v.salePriceCent??v.priceCent):v.capacity?`${v.capacity}人`:'-'}}</td><td><template v-if="configTab==='dishes'"><b :class="{'stock-negative':v.lowStock}">{{v.availableQuantity}}</b><small>总{{v.onHandQuantity}} / 锁定{{v.lockedQuantity}} / 预警{{v.warningQuantity}}</small></template><template v-else-if="configTab==='packages'">{{(v.items||[]).map(x=>`${x.dishName}×${x.quantity}`).join('、')}}</template><template v-else>-</template></td><td><span class="badge">{{status(v.status)}}</span><small>{{v.special?'特价 ':''}}{{v.recommended?'推荐':''}}</small></td><td><button @click="open({stores:'store',tables:'table',categories:'category',dishes:'dish',packages:'package'}[configTab],v)">编辑</button> <button v-if="configTab==='dishes'" @click="open('stock',v)">库存</button></td></tr></tbody></table></div></section>
<section v-if="tab==='orders'"><div class="filters"><select v-model="statusFilter"><option value="">全部状态</option><option v-for="(t,v) in statusText" :key="v" :value="v">{{t}}</option></select><button class="primary" @click="loadOrders">查询</button><button @click="csv">导出CSV</button></div><div class="panel table-wrap"><table><thead><tr><th>预订/订单</th><th>门店/类型</th><th>预订时间</th><th>顾客</th><th>点餐/金额</th><th>状态/操作</th></tr></thead><tbody><tr v-if="!orders.length"><td colspan="6">暂无订单。</td></tr><tr v-for="v in orders" :key="v.id"><td><b>{{v.reservationNo}}</b><small>{{v.orderNo}}</small></td><td>{{v.storeName}}<small>{{v.fulfillmentType}} · {{v.tableName||'无餐位'}}</small></td><td>{{v.reservationDate}}<small>{{v.reservationTime}} · {{v.guestCount}}人</small></td><td>{{v.contactName}}<small>{{v.contactMobile}}</small></td><td>{{money(v.totalAmountCent)}}<small>{{v.items.map(x=>`${x.itemName}×${x.quantity}`).join('、')}}</small></td><td><span class="badge">{{status(v.status)}}</span><button v-if="v.fulfillmentType==='DELIVERY'&&v.status==='READY'" class="primary" @click="startDelivery(v)">开始配送</button><button v-if="v.status==='DELIVERING'||(v.fulfillmentType!=='DELIVERY'&&['VERIFIED','READY'].includes(v.status))" class="primary" @click="complete(v)">完成</button></td></tr></tbody></table></div></section>
<section v-if="tab==='kitchen'"><div class="toolbar"><div><h3>后厨与前台实时任务</h3><p>支付成功后同步生成两端任务，按接单、备好、完成顺序处理。</p></div><button @click="loadKitchen">刷新任务</button></div><div class="ticket-grid"><article v-for="v in tickets" :key="v.id" class="panel"><header><b>{{v.station==='KITCHEN'?'后厨':'前台'}} · {{v.reservationNo}}</b><span class="badge">{{status(v.status)}}</span></header><h3>{{v.storeName}} · {{v.fulfillmentType}}</h3><p>{{v.reservationDate}} {{v.reservationTime}}</p><ul><li v-for="i in v.items" :key="i.itemCode">{{i.itemName}} × {{i.quantity}}</li></ul><footer><button v-if="v.status==='NEW'" class="primary" @click="kitchen(v,'ACCEPTED')">接单</button><button v-if="v.status==='ACCEPTED'" class="primary" @click="kitchen(v,'READY')">备餐完成</button><button v-if="v.status==='READY'" @click="kitchen(v,'COMPLETED')">任务完成</button></footer></article></div></section>
<section v-if="tab==='verify'"><div class="verify panel"><div><h3>堂食扫码核销</h3><p>仅支持堂食订单；宾馆内部配送订单必须按配送流程完成，重复核销会被状态锁拦截。</p></div><label>设备号<input v-model="device"></label><label>核销码<input v-model.trim="verifyCode" placeholder="BFDI-…" @keyup.enter="consume"></label><button class="primary" :disabled="!verifyCode" @click="consume">确认核销</button></div></section>
<section v-if="tab==='report'"><div class="toolbar"><div><h3>餐饮营业数据</h3><p>汇总营业额、订单、人次、核销、退款及菜品销量。</p></div><div><button class="primary" @click="loadReport">生成报表</button> <button @click="csv">导出CSV</button></div></div><div class="report-stats"><article v-for="v in cards" :key="v[0]"><span>{{v[0]}}</span><strong>{{v[1]}}</strong><small>{{v[2]}}</small></article></div><div class="panel table-wrap"><table><thead><tr><th>菜品/套餐</th><th>类型</th><th>销售数量</th><th>销售额</th></tr></thead><tbody><tr v-for="v in sales" :key="`${v.itemType}-${v.itemId}`"><td>{{v.itemName}}</td><td>{{v.itemType}}</td><td>{{v.quantity}}</td><td>{{money(v.salesAmountCent)}}</td></tr></tbody></table></div></section>
<div v-if="modal" class="modal-backdrop" @click.self="modal='' "><section class="modal panel"><div class="toolbar"><h3>餐饮资料维护</h3><button @click="modal=''">×</button></div><div class="form-grid"><template v-if="modal==='store'"><label>门店编码<input v-model="form.storeCode"></label><label>名称<input v-model="form.name"></label><label class="wide">地址<input v-model="form.address"></label><label>电话<input v-model="form.contactPhone"></label><label>营业开始<input v-model="form.openTime" type="time"></label><label>营业结束<input v-model="form.closeTime" type="time"></label></template><template v-if="modal==='table'"><label>门店<select v-model="form.storeId"><option v-for="s in stores" :key="s.id" :value="s.id">{{s.name}}</option></select></label><label>编码<input v-model="form.tableCode"></label><label>名称<input v-model="form.name"></label><label>类型<select v-model="form.tableType"><option value="TABLE">餐位</option><option value="PRIVATE_ROOM">雅间</option></select></label><label>容量<input v-model.number="form.capacity" type="number"></label></template><template v-if="modal==='category'"><label>门店<select v-model="form.storeId"><option v-for="s in stores" :key="s.id" :value="s.id">{{s.name}}</option></select></label><label>分类编码<input v-model="form.categoryCode"></label><label>名称<input v-model="form.name"></label><label>排序<input v-model.number="form.sortOrder" type="number"></label></template><template v-if="modal==='dish'"><label>门店<select v-model="form.storeId"><option v-for="s in stores" :key="s.id" :value="s.id">{{s.name}}</option></select></label><label>分类<select v-model="form.categoryId"><option v-for="c in categories.filter(x=>String(x.storeId)===String(form.storeId))" :key="c.id" :value="c.id">{{c.name}}</option></select></label><label>菜品编码<input v-model="form.dishCode"></label><label>名称<input v-model="form.name"></label><label>原价（元）<input v-model.number="form.priceYuan" type="number" step=".01"></label><label>特价（元）<input v-model.number="form.specialPriceYuan" type="number" step=".01"></label><label>初始库存<input v-model.number="form.initialStock" type="number"></label><label>预警库存<input v-model.number="form.warningQuantity" type="number"></label><label>推荐<input v-model="form.recommended" type="checkbox"></label><label>特价菜<input v-model="form.special" type="checkbox"></label><label class="wide">图片URL<input v-model="form.imageUrl"></label></template><template v-if="modal==='package'"><label>门店<select v-model="form.storeId"><option v-for="s in stores" :key="s.id" :value="s.id">{{s.name}}</option></select></label><label>套餐编码<input v-model="form.packageCode"></label><label>名称<input v-model="form.name"></label><label>价格（元）<input v-model.number="form.priceYuan" type="number" step=".01"></label><label class="wide">套餐菜品（菜品ID:数量，逗号分隔）<input v-model="form.itemText" placeholder="1:2,3:1"></label><label>推荐<input v-model="form.recommended" type="checkbox"></label></template><template v-if="modal==='stock'"><p class="wide">{{form.dish?.name}} · 当前可售 {{form.dish?.availableQuantity}}</p><label>操作<select v-model="form.operation"><option value="IN">入库</option><option value="OUT">出库</option></select></label><label>数量<input v-model.number="form.quantity" type="number"></label><label class="wide">备注<input v-model="form.remark"></label></template><label v-if="!['stock'].includes(modal)">状态<select v-model="form.status"><option value="ACTIVE">启用</option><option value="INACTIVE">停用</option></select></label></div><div class="modal-actions"><button @click="modal=''">取消</button><button class="primary" @click="save">保存</button></div></section></div></div></template>
<style scoped>.msg{margin:0 0 12px}.context,.filters{display:flex;align-items:end;gap:12px;margin-bottom:16px}.context label,.form-grid label,.verify label{display:grid;gap:5px;font-size:12px;color:#607167}.context input,.context select,.filters select,.form-grid input,.form-grid select,.verify input{padding:9px;border:1px solid #dce6e0;border-radius:8px;background:#fff}.config-nav{display:flex;gap:8px;margin:14px 0}.config-nav .active{color:#fff;background:#176b58}.ticket-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}.ticket-grid header,.ticket-grid footer{display:flex;justify-content:space-between;gap:8px}.ticket-grid ul{padding-left:20px;min-height:60px}.verify{display:grid;grid-template-columns:1.5fr 1fr 1fr auto;align-items:end;gap:14px}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.wide{grid-column:1/-1}.modal{width:min(760px,100%)}.report-stats{grid-template-columns:repeat(5,1fr)}@media(max-width:1000px){.ticket-grid{grid-template-columns:1fr 1fr}.report-stats{grid-template-columns:1fr 1fr}.verify{grid-template-columns:1fr 1fr}}@media(max-width:700px){.context,.verify{display:flex;flex-direction:column;align-items:stretch}.ticket-grid,.form-grid,.report-stats{grid-template-columns:1fr}.wide{grid-column:auto}}</style>
